# 2005年江苏卷
add_exam_question(2005, "江苏卷", "选择题", "下列关于细胞膜的叙述，正确的是（）", ["A. 细胞膜主要由蛋白质构成", "B. 细胞膜具有选择透过性", "C. 细胞膜上没有糖类", "D. 细胞膜是完全对称的"], "B", "细胞膜主要由磷脂和蛋白质构成，含有少量糖类，结构不对称，具有选择透过性。")
add_exam_question(2005, "江苏卷", "选择题", "下列关于酶的叙述，错误的是（）", ["A. 酶具有高效性", "B. 酶具有专一性", "C. 酶的活性不受温度影响", "D. 酶绝大多数是蛋白质"], "C", "酶的活性受温度、pH等因素影响，在最适温度下活性最高。")
add_exam_question(2005, "江苏卷", "选择题", "光合作用的光反应阶段发生的场所是（）", ["A. 叶绿体基质", "B. 类囊体薄膜", "C. 线粒体基质", "D. 细胞质基质"], "B", "光合作用的光反应在类囊体薄膜上进行，暗反应在叶绿体基质中进行。")
add_exam_question(2005, "江苏卷", "选择题", "下列关于DNA复制的叙述，正确的是（）", ["A. 只在细胞核中进行", "B. 需要RNA引物", "C. 以RNA为模板", "D. 不需要酶的参与"], "B", "DNA复制需要RNA引物，主要在细胞核中进行，也可在线粒体和叶绿体中进行。")
add_exam_question(2005, "江苏卷", "选择题", "下列属于体液调节的是（）", ["A. 膝跳反射", "B. 甲状腺激素调节", "C. 缩手反射", "D. 眨眼反射"], "B", "体液调节主要通过激素等化学物质进行，甲状腺激素调节属于体液调节。")
add_exam_question(2005, "江苏卷", "选择题", "下列关于种群特征的叙述，正确的是（）", ["A. 年龄组成只影响种群出生率", "B. 性别比例只影响种群死亡率", "C. 出生率和死亡率是决定种群密度的直接因素", "D. 种群密度能反映种群数量的变化趋势"], "C", "出生率和死亡率直接决定种群密度；年龄组成影响出生率和死亡率。")
add_exam_question(2005, "江苏卷", "选择题", "下列关于生态系统的叙述，错误的是（）", ["A. 生态系统的能量流动是单向的", "B. 生态系统的物质循环具有全球性", "C. 信息传递只发生在生物之间", "D. 生态系统具有一定的自我调节能力"], "C", "信息传递发生在生物与生物之间、生物与无机环境之间。")
add_exam_question(2005, "江苏卷", "选择题", "下列关于免疫调节的叙述，正确的是（）", ["A. 抗体能直接杀死病原体", "B. 效应T细胞能产生抗体", "C. 体液免疫主要针对细胞内的抗原", "D. 免疫系统具有防卫、监控和清除功能"], "D", "抗体不能直接杀死病原体，只能与抗原结合；效应T细胞不能产生抗体。")
add_exam_question(2005, "江苏卷", "填空题", "细胞呼吸的主要场所是________，光合作用的产物是________和________。", ["", "", "", ""], "线粒体；糖类（或葡萄糖）；氧气", "细胞呼吸主要在线粒体中进行；光合作用产生糖类等有机物和氧气。")
add_exam_question(2005, "江苏卷", "填空题", "DNA分子的基本组成单位是________，其含有的五碳糖是________。", ["", "", "", ""], "脱氧核苷酸；脱氧核糖", "DNA的基本组成单位是脱氧核苷酸，由脱氧核糖、磷酸和含氮碱基组成。")
