add_exam_question(2006, "湖北卷", "选择题", "下列关于生态系统的叙述，错误的是（）", ["A. 生态系统的能量流动是单向的", "B. 生态系统的物质循环具有全球性", "C. 信息传递只发生在生物之间", "D. 生态系统具有一定的自我调节能力"], "C", "信息传递发生在生物与生物之间、生物与无机环境之间。")
add_exam_question(2006, "湖北卷", "选择题", "下列关于免疫调节的叙述，正确的是（）", ["A. 抗体能直接杀死病原体", "B. 效应T细胞能产生抗体", "C. 体液免疫主要针对细胞内的抗原", "D. 免疫系统具有防卫、监控和清除功能"], "D", "抗体不能直接杀死病原体，只能与抗原结合；效应T细胞不能产生抗体。")
add_exam_question(2006, "湖北卷", "填空题", "细胞呼吸的主要场所是________，光合作用的产物是________和________。", ["", "", "", ""], "线粒体；糖类（或葡萄糖）；氧气", "细胞呼吸主要在线粒体中进行；光合作用产生糖类等有机物和氧气。")
add_exam_question(2006, "湖北卷", "填空题", "DNA分子的基本组成单位是________，其含有的五碳糖是________。", ["", "", "", ""], "脱氧核苷酸；脱氧核糖", "DNA的基本组成单位是脱氧核苷酸，由脱氧核糖、磷酸和含氮碱基组成。")
add_exam_question(2006, "湖北卷", "解答题", "某植物种群中，AA基因型个体占30%，aa基因型个体占20%。（1）该种群中A和a的基因频率分别是多少？（2）若该种群进行自交，后代中AA、Aa、aa基因型频率分别是多少？", ["", "", "", ""], "（1）A=55%，a=45%；（2）AA=42.5%，Aa=25%，aa=32.5%", "（1）Aa=50%，A=30%+50%×1/2=55%，a=20%+50%×1/2=45%。（2）AA自交后代全为AA（30%），Aa自交后代AA=50%×1/4=12.5%，Aa=50%×1/2=25%，aa=50%×1/4=12.5%，aa自交后代全为aa（20%）。合计AA=42.5%，Aa=25%，aa=32.5%。")
# 2006年湖南卷
