add_exam_question(2023, "河北卷", "填空题", "DNA分子的基本组成单位是________，其含有的五碳糖是________。", ["", "", "", ""], "脱氧核苷酸；脱氧核糖", "DNA的基本组成单位是脱氧核苷酸，由脱氧核糖、磷酸和含氮碱基组成。")
add_exam_question(2023, "河北卷", "解答题", "某植物种群中，AA基因型个体占30%，aa基因型个体占20%。（1）该种群中A和a的基因频率分别是多少？（2）若该种群进行自交，后代中AA、Aa、aa基因型频率分别是多少？", ["", "", "", ""], "（1）A=55%，a=45%；（2）AA=42.5%，Aa=25%，aa=32.5%", "（1）Aa=50%，A=30%+50%×1/2=55%，a=20%+50%×1/2=45%。（2）AA自交后代全为AA（30%），Aa自交后代AA=50%×1/4=12.5%，Aa=50%×1/2=25%，aa=50%×1/4=12.5%，aa自交后代全为aa（20%）。合计AA=42.5%，Aa=25%，aa=32.5%。")
# 2023年四川卷
add_exam_question(2023, "四川卷", "选择题", "下列关于细胞膜的叙述，正确的是（）", ["A. 细胞膜主要由蛋白质构成", "B. 细胞膜具有选择透过性", "C. 细胞膜上没有糖类", "D. 细胞膜是完全对称的"], "B", "细胞膜主要由磷脂和蛋白质构成，含有少量糖类，结构不对称，具有选择透过性。")
add_exam_question(2023, "四川卷", "选择题", "下列关于酶的叙述，错误的是（）", ["A. 酶具有高效性", "B. 酶具有专一性", "C. 酶的活性不受温度影响", "D. 酶绝大多数是蛋白质"], "C", "酶的活性受温度、pH等因素影响，在最适温度下活性最高。")
add_exam_question(2023, "四川卷", "选择题", "光合作用的光反应阶段发生的场所是（）", ["A. 叶绿体基质", "B. 类囊体薄膜", "C. 线粒体基质", "D. 细胞质基质"], "B", "光合作用的光反应在类囊体薄膜上进行，暗反应在叶绿体基质中进行。")
add_exam_question(2023, "四川卷", "选择题", "下列关于DNA复制的叙述，正确的是（）", ["A. 只在细胞核中进行", "B. 需要RNA引物", "C. 以RNA为模板", "D. 不需要酶的参与"], "B", "DNA复制需要RNA引物，主要在细胞核中进行，也可在线粒体和叶绿体中进行。")
